public class MaskingVariable
{
    public static void main(String[] args)
    {
        int aNumber = 10;
        firstMethod();
        secondMethod(aNumber);
        System.out.println(aNumber);
    }
    public static void firstMethod()
    {
        int aNumber = 77;
        System.out.println(aNumber);
    }
    public static void secondMethod(int aNumber)
    {
        aNumber = 862;
        System.out.println(aNumber);
    }
}

